    }

    let Value::Ptr(Pointer { thin_pointer: ptr, metadata: None }) = arguments[0].0 else {
        throw_ub!("invalid first argument to `AtomicLoad` intrinsic: not a thin pointer");
    };

    let size = ret_ty.layout::<M::T>().expect_size("WF ensures intrinsic return types are sized");
    let Some(align) = Align::from_bytes(size.bytes()) else {
        throw_ub!("invalid return type for `AtomicLoad` intrinsic: size not power of two");
    };
    if size > M::T::MAX_ATOMIC_SIZE {
        throw_ub!("invalid return type for `AtomicLoad` intrinsic: size too big");
    }

    // `ret_ty` is ensured to be sized above.
    let val = self.typed_load(ptr, ret_ty, align, Atomicity::Atomic)?;
    ret(val)
}

}
rs::StatementKind::Intrinsic(intrinsic) => {
    match &**intrinsic {
        rs::NonDivergingIntrinsic::Assume(op) => {
            let op = self.translate_operand(op, span);
            // Doesn't return anything, get us a dummy place.
            let destination = build::unit_place();
            return StatementResult::Intrinsic {
                intrinsic: IntrinsicOp::Assume,
                destination,
                arguments: list![op],
            };
        }
        rs::NonDivergingIntrinsic::CopyNonOverlapping(_) =>
            rs::span_bug!(span, "NonDivergingIntrinsic not supported: {intrinsic:?}"),
    }
}
rs::StatementKind::PlaceMention(place) => {

        ret: self.translate_place(&destination, span),
        next_block: target.as_ref().map(|t| self.bb_name_map[t]),
    }
} else if is_panic_fn(&instance.to_string()) {
    // We can't translate this call, it takes a string. As a hack we just ignore the argument.
    self.translate_panic(unwind, bb)
} else if self.tcx.is_foreign_item(instance.def_id()) {
    // Foreign functions don't have MIR.
    rs::span_bug!(span, "cannot call foreign function {instance}");
} else {
    let abi = self
        .cx
        .tcx
        .fn_abi_of_instance(self.typing_env().as_query_input((instance, rs::List::empty())))
        .unwrap();
